import {studio} from './app.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={
 import:'<path d="M3 15V6a3 3 0 0 1 3-3h10a3 3 0 0 1 3 3v6M3 14l5-5 5 5 3-3 3 3M17 17h6m-3-3v6"/>',
 double:'<rect x="3" y="3" width="13" height="13" rx="4"/><rect x="8" y="8" width="13" height="13" rx="4"/>',
 timer:'<circle cx="12" cy="14" r="8"/><path d="M9 2h6m-3 4v8"/>',
 flash:'<path d="m13 2-5 11h5l-2 9 6-13h-5z"/>',
 flip:'<path d="M3 10a9 9 0 0 1 15-5l3 4m-1-6 1 6-6-1M21 14A9 9 0 0 1 6 19l-3-4m1 6-1-6 6 1"/>',
 film:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 4v16m8-16v16M4 8h4m-4 4h4m-4 4h4m8-8h4m-4 4h4m-4 4h4"/>',
 temperature:'<path d="M10 5a2 2 0 0 1 4 0v9a4 4 0 1 1-4 0z"/><path d="M12 9v9"/>',
 sun:'<circle cx="12" cy="12" r="3"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 bulb:'<path d="M9 18c0-5-4-5-4-10a7 7 0 0 1 14 0c0 5-4 5-4 10zm0 3h6m-5 2h4"/>',
 down:'<path d="m5 9 7 7 7-7"/>',
 reset:'<path d="m9 3-6 5 6 4M3 8h10a7 7 0 1 1-2 14"/>',
 camera:'<path d="M3 7h5l2-3h5l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',
 frame:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M6 11V8h3m6 8h3v-3"/>',
 grid:'<path d="M8 3v18m8-18v18M3 8h18M3 16h18"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.camera}</svg>`;}
function element(tag,id,html){const e=document.createElement(tag);e.id=id;e.innerHTML=html;return e;}
const viewfinder=$('#viewfinder');viewfinder.append(element('div','focus-frame','<span id="focal-caption">42mm</span>'));
const menu=element('button','view-menu','···');menu.setAttribute('aria-label','Opções da câmera');viewfinder.append(menu);
const badges=element('div','view-badges',`<button id="film-control" aria-label="Ajustes do filme">${icon('film')}</button><span class="badge-space"></span><button id="temperature-control" aria-label="Balanço de branco">${icon('temperature')}</button><button id="focal-control" aria-label="Distância focal"><span>42</span></button><button id="exposure-control" aria-label="Exposição">${icon('sun')}<span>0</span></button>`);viewfinder.append(badges);
const toolbar=element('div','native-tools','');toolbar.className='native-tools';
const importButton=$('#import-bottom');importButton.innerHTML=icon('import');toolbar.append(importButton);
const double=element('button','double-control',icon('double'));double.setAttribute('aria-label','Dupla exposição');toolbar.append(double);
for(const [id,name]of [['timer','timer'],['flash','flash'],['flip','flip']]){const button=$('#'+id);button.innerHTML=icon(name)+(id==='timer'?'<small hidden>0s</small>':'');toolbar.append(button);}
$('.camera-controls').append(toolbar);
const nativePicker=element('button','native-picker','<span class="native-camera-icon grdr"></span>');nativePicker.setAttribute('aria-label','Selecionar câmera');$('.capture-row').append(nativePicker);
const toggle=element('button','bottom-toggle','−');toggle.setAttribute('aria-label','Alternar enquadramento');$('.camera-shell').append(toggle);toggle.onclick=()=>{document.body.classList.toggle('native-preview-full');};
const panel=element('div','native-panel','');panel.hidden=true;$('.camera-controls').append(panel);
const options=element('dialog','native-options',`<div class="dialog-heading"><h2>Ajustes da câmera</h2><button aria-label="Fechar ajustes" id="options-close">×</button></div><div class="option-grid"><button id="native-open-camera">Abrir câmera</button><button id="native-import">Importar foto / vídeo</button><button id="native-photo">Foto</button><button id="native-video">Vídeo</button><button id="native-grid">Grade</button><button id="native-collage">Colagem</button><button id="native-settings">Preferências</button><button id="native-demo">Imagem de demonstração</button></div>`);document.body.append(options);options.append($('#camera-view .inspector'));$('#options-close').onclick=()=>options.close();menu.onclick=()=>options.showModal();$('#film-control').onclick=()=>options.showModal();
$('#native-open-camera').onclick=()=>{options.close();studio.startCamera();};$('#native-import').onclick=()=>{options.close();$('#file-input').click();};$('#native-photo').onclick=()=>{studio.setMode('photo');options.close();};$('#native-video').onclick=()=>{studio.setMode('video');options.close();};$('#native-grid').onclick=()=>{studio.update({grid:!studio.settings.grid});$('#focus-frame').classList.toggle('no-grid',!studio.settings.grid);};$('#native-collage').onclick=()=>{options.close();studio.setView('collage');};$('#native-settings').onclick=()=>{options.close();$('#settings-dialog').showModal();};$('#native-demo').onclick=()=>{options.close();$('#demo').click();};
for(const id of ['gallery','collage']){const back=element('button','back-'+id,'‹ Câmera');back.className='back-camera';back.onclick=()=>studio.setView('camera');$('#'+id+'-view').prepend(back);}
let activePanel=null;
function closePanel(){activePanel=null;panel.hidden=true;toolbar.hidden=false;$$('#view-badges button').forEach(b=>b.classList.remove('active'));}
function showPanel(type){if(activePanel===type){closePanel();return;}activePanel=type;panel.hidden=false;toolbar.hidden=true;$$('#view-badges button').forEach(b=>b.classList.toggle('active',b.id===type+'-control'));if(type==='exposure'){panel.innerHTML=`<div class="native-ev"><button id="ev-reset" aria-label="Redefinir exposição">${icon('reset')}</button><button id="ev-auto" class="auto" aria-label="Exposição automática">A</button><label><output id="ev-output">${studio.settings.exposure}</output><input id="ev-native" type="range" min="-5" max="5" step=".1" value="${studio.settings.exposure}" aria-label="Exposição EV"></label></div>`;$('#ev-native').oninput=e=>{studio.update({exposure:+e.target.value});$('#ev-output').textContent=e.target.value;syncBadges();};for(const id of ['ev-auto','ev-reset'])$('#'+id).onclick=()=>{studio.update({exposure:0});$('#ev-native').value=0;$('#ev-output').textContent='0';syncBadges();};}else if(type==='temperature'){panel.innerHTML=`<div class="native-wb"><div class="wb-plane" role="slider" aria-label="Temperatura e matiz" aria-valuemin="2000" aria-valuemax="10000" aria-valuenow="6500" tabindex="0"><output id="wb-output">6500K 0</output><i></i></div><button id="wb-auto" aria-label="Balanço automático">A</button><button id="wb-daylight" aria-label="Luz do dia">${icon('sun')}</button><button id="wb-tungsten" aria-label="Luz de tungstênio">${icon('bulb')}</button></div>`;const plane=$('.wb-plane');const update=(x,y)=>{const kelvin=Math.round(2000+x*8000),tint=Math.round((.5-y)*80);studio.update({temperature:Math.round((kelvin-6500)/55),tint});plane.setAttribute('aria-valuenow',kelvin);$('.wb-plane i').style.left=`calc(${x*100}% - 9px)`;$('.wb-plane i').style.top=`calc(${y*100}% - 9px)`;$('#wb-output').textContent=`${kelvin}K ${tint}`;};const point=e=>{const r=plane.getBoundingClientRect();update(Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)));};plane.onpointerdown=e=>{plane.setPointerCapture(e.pointerId);point(e);};plane.onpointermove=e=>{if(e.buttons)point(e);};plane.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const value=+plane.getAttribute('aria-valuenow')+(e.key==='ArrowRight'?100:-100);update(Math.max(0,Math.min(1,(value-2000)/8000)),.5);}};$('#wb-auto').onclick=()=>update(.5625,.5);$('#wb-daylight').onclick=()=>update(.4375,.5);$('#wb-tungsten').onclick=()=>update(.125,.5);}else if(type==='focal'){panel.innerHTML=[13,26,35,50].map(mm=>`<button class="focal-option" data-mm="${mm}">${mm}${mm===13?'<small>.5x</small>':mm===26?'<small>1x</small>':''}</button>`).join('');$$('[data-mm]').forEach(b=>b.onclick=()=>{const mm=+b.dataset.mm;studio.update({zoom:Math.max(1,mm/26),focal:mm});syncBadges();if(mm===13)studio.toast('13 mm exige uma lente ultrawide. Usando o campo disponível da câmera.');closePanel();});}}
$('#temperature-control').onclick=()=>showPanel('temperature');$('#exposure-control').onclick=()=>showPanel('exposure');$('#focal-control').onclick=()=>showPanel('focal');
double.onclick=()=>{const next=studio.mode==='double'?'photo':'double';studio.setMode(next);double.classList.toggle('active',next==='double');studio.toast(next==='double'?'Dupla exposição: capture o primeiro e depois o segundo quadro.':'Modo foto.');};
function syncBadges(){const ev=studio.settings.exposure;$('#exposure-control span').textContent=Number(ev.toFixed(1));const focal=studio.settings.focal||Math.round(studio.settings.zoom*26);$('#focal-control span').textContent=focal;$('#focal-caption').textContent=focal+'mm';}
// The screen recording establishes appearance and names; recipes remain approximations.
const extra=[['dam','DAM','Vídeo'],['vclassic','V Classic','Vídeo'],['originalv','Original V','Vídeo'],['vfuns','V FunS','Vídeo'],['instss','Inst SS','Vídeo'],['slidep','Slide P','Vídeo'],['dcr','DCR','Vídeo'],['glow','Glow','Vídeo'],['fxnr','FXN','Foto'],['dexp','D Exp','Foto'],['fqs','FQS','Foto'],['classicu','Classic U','Foto'],['puli','Puli','Foto'],['kv88','KV88','Foto'],['srx','SRX','Foto'],['dfuns','D FunS','Foto']];
for(const [id,name,family]of extra){if(!studio.cameras.some(c=>c.id===id)){const base=studio.cameras.find(c=>c.id===(family==='Vídeo'?'kino':'classic'));studio.cameras.push({...base,id,name,family,desc:`Interpretação web da câmera ${name}.`});}}
const sprites={
 dam:['a',65,410],vclassic:['a',148,410],originalv:['a',231,410],vfuns:['a',312,410],
 fxnr:['a',48,537],dexp:['a',132,537],fqs:['a',214,537],classicu:['a',297,537],
 instss:['b',24,410],kino:['b',105,410], '16mm':['b',187,410],slidep:['b',270,410],
 ofm:['b',71,537],puli:['b',154,537],instsq:['b',236,537],kv88:['b',320,537],
 grd:['c',314,537],dfuns:['a',0,537]
};
function sprite(id){const s=sprites[id];return s?`<span class="native-camera-icon" style="background-image:url('assets/camera-sprite-${s[0]}.png');background-position:-${s[1]}px -${s[2]}px"></span>`:`<span class="native-camera-icon generic" style="--camera-color:${studio.cameras.find(c=>c.id===id)?.color||'#777'}"></span>`;}
const videoIds=['8mm','dam','vclassic','originalv','vfuns','instss','kino','16mm','slidep','dcr','glow'];const photoIds=['dfuns','fxnr','dexp','fqs','classicu','grd','kv88','classic','ofm','puli','instsq','srx','ccdr','instc','dblack','s67','135ne','dhalf','original'];
function drawPicker(){const catalog=$('#camera-catalog');catalog.innerHTML=[videoIds,photoIds].map((ids,row)=>`<div class="camera-film-row" aria-label="${row?'Câmeras fotográficas':'Câmeras de vídeo'}">${ids.map(id=>{const c=studio.cameras.find(c=>c.id===id);return `<button class="camera-tile ${studio.settings.camera===id?'selected':''}" data-native-camera="${id}" aria-label="${c.name}">${sprite(id)}<strong>${id==='grd'?'GRD':c.name}${['grd','fxnr','fqs','ofm','srx'].includes(id)?'<b>R</b>':''}</strong></button>`;}).join('')}</div>`).join('');const rows=$$('.camera-film-row');rows[0].scrollLeft=37;rows[1].scrollLeft=120;$$('[data-native-camera]').forEach(b=>b.onclick=()=>{studio.chooseCamera(b.dataset.nativeCamera);const loading=element('div','lens-loading','<svg viewBox="0 0 100 100"><defs><clipPath id="rainbow-circle"><circle cx="50" cy="50" r="46"/></clipPath></defs><g clip-path="url(#rainbow-circle)" transform="rotate(-35 50 50)"><path d="M0 0h100v15H0z" fill="#e9d929"/><path d="M0 20h100v14H0z" fill="#36c867"/><path d="M0 40h100v14H0z" fill="white"/><path d="M0 60h100v14H0z" fill="#3274c7"/><path d="M0 80h100v14H0z" fill="#bd4545"/></g></svg>');$('.camera-shell').append(loading);setTimeout(()=>loading.remove(),220);if(['instsq','instc'].includes(b.dataset.nativeCamera)){studio.update({ratio:'2:3'});}if(b.dataset.nativeCamera==='dexp')studio.setMode('double');nativePicker.innerHTML=sprite(b.dataset.nativeCamera);closePanel();syncBadges();});}
const picker=$('#cameras-dialog');picker.append(element('div','picker-actions',`<button class="sample" id="picker-sample">${icon('camera')} AMOSTRA</button><button id="picker-manage" aria-label="Lista de câmeras">☰</button><button id="picker-favorites" aria-label="Câmeras favoritas">🌷</button>`));
picker.append(element('div','picker-accessories',`<button class="red-lens" id="lens-leak" aria-label="Vazamento de luz vermelho"></button><button class="prism-lens" id="lens-prism" aria-label="Efeito prisma">✧</button><button id="lens-border" aria-label="Moldura de filme">${icon('frame')}</button>`));
const close=element('button','picker-close',icon('down'));close.setAttribute('aria-label','Voltar à câmera');close.onclick=()=>picker.close();picker.append(close);
function openNativePicker(){drawPicker();picker.showModal();requestAnimationFrame(()=>{const rows=$$('.camera-film-row');rows[0].scrollLeft=37;rows[1].scrollLeft=120;});}nativePicker.onclick=openNativePicker;$('#camera-picker').onclick=openNativePicker;
$('#picker-sample').onclick=()=>{picker.close();$('#demo').click();};let listMode=false;$('#picker-manage').onclick=()=>{listMode=!listMode;$('#camera-catalog').classList.toggle('list-mode',listMode);};
let favoriteIds;try{favoriteIds=JSON.parse(localStorage.getItem('dazz-favorite-cameras')||'[]');}catch{favoriteIds=[];}
$('#picker-favorites').onclick=()=>{const id=studio.settings.camera;if(favoriteIds.includes(id))favoriteIds=favoriteIds.filter(x=>x!==id);else favoriteIds.push(id);localStorage.setItem('dazz-favorite-cameras',JSON.stringify(favoriteIds));studio.toast(favoriteIds.includes(id)?'Câmera atual adicionada às favoritas.':'Câmera removida das favoritas.');drawPicker();for(const b of $$('[data-native-camera]'))if(favoriteIds.includes(b.dataset.nativeCamera))b.querySelector('strong').append(' ♥');};
$('#lens-leak').onclick=e=>{const on=studio.settings.leak===0;studio.update({leak:on?55:0});e.currentTarget.classList.toggle('selected',on);};$('#lens-prism').onclick=e=>{const on=!studio.settings.prism;studio.update({prism:on});e.currentTarget.classList.toggle('selected',on);};$('#lens-border').onclick=e=>{const on=studio.settings.frame!=='film';studio.update({frame:on?'film':'none'});e.currentTarget.classList.toggle('selected',on);};
window.addEventListener('camera-changed',()=>{nativePicker.innerHTML=sprite(studio.settings.camera);syncBadges();});
if(!localStorage.getItem('dazz-replica-initialized')){studio.update({camera:'grd',ratio:'2:3',zoom:42/26,focal:42,grid:true});localStorage.setItem('dazz-replica-initialized','1');}
syncBadges();nativePicker.innerHTML=sprite(studio.settings.camera);$('#focus-frame').classList.toggle('no-grid',!studio.settings.grid);
